BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Clearly trivial threshold definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does the term ''clearly trivial'' mean when applied to misstatements identified during an audit?', '["Misstatements that are inconsequential both individually and in the aggregate", "Misstatements that fall below the tolerable misstatement threshold", "Misstatements resulting from errors rather than fraud", "Misstatements that management has already corrected during the audit"]'::jsonb, 0, 'Under AU-C 450.A2, ''clearly trivial'' describes misstatements that are inconsequential both individually and in the aggregate, meaning they need not be accumulated for evaluation. This threshold is set well below materiality. Choice B is incorrect because tolerable misstatement is a separate sampling concept unrelated to the clearly trivial threshold used for accumulating audit differences.', 'easy', 1),

-- Q2: hard / L4 — Iron curtain vs rollover evaluation approach
(1, 'Misstatements and Control Deficiencies', 'During the audit of Grandview Electronics, the engagement partner identifies $18,000 in uncorrected prior-year misstatements that reverse in the current year and $12,000 in new current-year misstatements. Under the rollover approach the net current-year impact is $12,000 (below $40,000 materiality), but under the iron curtain approach the cumulative balance-sheet effect is $30,000. The partner must evaluate which approach best represents the financial statements. What is the most appropriate course of action?', '["Use only the rollover approach because prior-year misstatements were previously evaluated", "Use only the iron curtain approach because it captures the cumulative balance-sheet effect", "Consider both approaches and use professional judgment to determine whether the aggregate misstatement is material", "Require management to correct the $18,000 prior-year misstatements before evaluating the current-year amount"]'::jsonb, 2, 'Under AU-C 450.A16, the auditor should consider both the iron curtain and rollover approaches when evaluating uncorrected misstatements because each highlights different aspects of the misstatement''s impact. Neither approach alone is sufficient. Choice B is incorrect because exclusively relying on the iron curtain method ignores the income statement effect, and SAB No. 108 (codified in ASC 250-10-S99) requires dual-method evaluation.', 'hard', 4),

-- Q3: medium / L2 — Tolerable misstatement and performance materiality application
(1, 'Misstatements and Control Deficiencies', 'Beacon Financial Group set overall materiality at $75,000 and performance materiality at $56,250 for the current-year audit. When testing accounts receivable, the auditor should set tolerable misstatement at:', '["$75,000, equal to overall materiality", "An amount at or below $56,250 based on the assessed risk for accounts receivable", "$37,500, which is exactly half of overall materiality", "An amount determined solely by dividing the accounts receivable balance by total assets"]'::jsonb, 1, 'Under AU-C 320.A13, performance materiality is set below overall materiality to reduce the probability that aggregate uncorrected and undetected misstatements exceed overall materiality. Tolerable misstatement for individual accounts is set at or below performance materiality based on assessed risk. Choice A is incorrect because using overall materiality directly for account-level testing creates an unacceptably high risk that aggregate misstatements across all accounts exceed materiality.', 'medium', 2),

-- Q4: hard / L4 — Evaluate adverse vs qualified opinion for pervasive misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgeway Capital Partners, the auditor identifies $320,000 in uncorrected misstatements across revenue, accounts receivable, and cash flows. Materiality is $250,000. Management refuses to make corrections. The misstatements affect multiple financial statement line items and disclosures throughout the statements. The engagement partner must evaluate the appropriate opinion modification. Which opinion is most appropriate?', '["Qualified opinion because the misstatements are material but confined to specific accounts", "Unmodified opinion with an emphasis-of-matter paragraph explaining the misstatements", "Disclaimer of opinion because management''s refusal creates a scope limitation", "Adverse opinion because the misstatements are both material and pervasive to the financial statements"]'::jsonb, 3, 'Under AU-C 705.08, when misstatements are both material and pervasive, the auditor should express an adverse opinion. Pervasiveness is evaluated based on whether misstatements affect multiple elements, accounts, or disclosures and are not confined to specific items. Choice A is incorrect because a qualified opinion is appropriate only when misstatements are material but not pervasive, meaning they are confined to specific elements of the financial statements.', 'hard', 4),

-- Q5: hard / L4 — Evaluate management bias in one-directional misstatements
(1, 'Misstatements and Control Deficiencies', 'While reviewing the summary of uncorrected misstatements for Lakewood Distributors, the auditor notes that all eight misstatements overstate net income, and seven of eight involve management estimates. The individual misstatements each fall below materiality, and the aggregate is $22,000 against a $50,000 materiality threshold. The engagement partner must assess whether these patterns indicate management bias. What is the best course of action?', '["Accept the misstatements without further action because the aggregate is below materiality", "Require management to correct all eight misstatements before issuing the audit report", "Increase the sample size for the current year''s testing of estimates to gather more evidence", "Evaluate whether the one-directional pattern indicates intentional bias and consider the effect on the auditor''s overall assessment of the financial statements"]'::jsonb, 3, 'Under AU-C 450.11, the auditor must consider whether uncorrected misstatements indicate possible bias in management''s judgments about estimates. A consistent one-directional pattern overstating income, particularly in estimates, is a strong indicator of potential bias even when the aggregate falls below materiality. Choice A is incorrect because AU-C 450 explicitly requires the auditor to evaluate qualitative aspects of misstatements, including patterns suggesting bias, regardless of the quantitative aggregate.', 'hard', 4),

-- Q6: medium / L2 — Misstatement in disclosures classification
(1, 'Misstatements and Control Deficiencies', 'Maple Creek Technologies omits a required disclosure about a $1.2 million related-party transaction in its December 2025 financial statements. The auditor identifies this during the review of disclosures. Under AU-C 450, this omission should be classified as:', '["A control deficiency rather than a misstatement because no account balance is affected", "An immaterial item because disclosures are supplementary to the financial statements", "A misstatement of the financial statements that must be evaluated for materiality", "A scope limitation that requires modification of the audit opinion regardless of materiality"]'::jsonb, 2, 'Under AU-C 450.04, misstatements include omissions of required disclosures, not just errors in account balances. The definition encompasses differences between the amount, classification, presentation, or disclosure of a reported financial statement item and what is required under the applicable framework. Choice A is incorrect because AU-C 450 explicitly includes disclosure omissions in the definition of misstatements, requiring the auditor to accumulate and evaluate them like quantitative errors.', 'medium', 2),

-- Q7: medium / L3 — IT general control deficiency impact on application controls
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ironwood Financial Services, the auditor discovers that the IT department lacks formal change management procedures for its accounting software. Three application controls—automated revenue cutoff, accounts payable matching, and payroll calculations—depend on this software operating correctly. What is the most likely effect of this IT general control deficiency on the audit approach?', '["The auditor should test each application control independently without considering the IT general control weakness", "The auditor should rely solely on inquiry of IT personnel about whether any unauthorized changes occurred", "The auditor may reduce substantive testing if the application controls produced accurate results during the period", "The auditor cannot rely on the three dependent application controls without additional compensating evidence"]'::jsonb, 3, 'Under AU-C 315.A72, IT general controls support the continued functioning of application controls. When a general control such as change management is deficient, the auditor cannot assume dependent application controls operated effectively throughout the period because unauthorized changes may have compromised their accuracy. Choice C is incorrect because the absence of change management means the auditor cannot determine whether the application controls functioned consistently, even if point-in-time testing shows correct results.', 'medium', 3),

-- Q8: medium / L3 — Qualitative factors overriding quantitative materiality
(1, 'Misstatements and Control Deficiencies', 'Sterling Aerospace has $42,000 in aggregate uncorrected misstatements against a materiality threshold of $50,000. One of the uncorrected misstatements converts a reported net profit of $15,000 into a net loss, and another causes a covenant violation on the company''s primary line of credit. The auditor must analyze the qualitative significance of these misstatements. Which conclusion is most appropriate?', '["The misstatements should be treated as material despite being below the quantitative threshold because of their qualitative significance", "The misstatements are immaterial because the aggregate amount does not exceed the materiality threshold", "The auditor should increase the materiality threshold to $60,000 to accommodate the qualitative considerations", "The auditor should request that management correct only the covenant-related misstatement"]'::jsonb, 0, 'Under AU-C 450.11, the auditor must consider qualitative factors when evaluating uncorrected misstatements, including effects on trends, debt covenant compliance, and whether a misstatement changes a profit to a loss. These qualitative impacts can render misstatements material even when they fall below quantitative thresholds. Choice B is incorrect because materiality is not determined solely by comparing aggregate misstatements to a numerical threshold—qualitative factors such as covenant violations and profit-to-loss changes must also be considered.', 'medium', 3),

-- Q9: easy / L1 — Deficiency in design vs deficiency in operation
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what is the distinction between a deficiency in design and a deficiency in operation of an internal control?', '["A design deficiency involves unauthorized access, while an operation deficiency involves processing errors", "A design deficiency exists when a control is missing or improperly designed, while an operation deficiency exists when a properly designed control does not operate effectively", "A design deficiency applies only to IT controls, while an operation deficiency applies to manual controls", "A design deficiency is always a material weakness, while an operation deficiency is always a significant deficiency"]'::jsonb, 1, 'Under AU-C 265.07, a deficiency in design exists when a necessary control is missing or not properly designed to meet the control objective, whereas a deficiency in operation exists when a properly designed control does not operate as designed or the person performing it lacks competence. Choice D is incorrect because neither type of deficiency is automatically classified as a material weakness or significant deficiency—the classification depends on the severity evaluation.', 'easy', 1),

-- Q10: easy / L1 — Error vs fraud distinction in misstatements
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, what is the primary distinction between an error and fraud when both result in misstatements of the financial statements?', '["Errors are always immaterial, while fraud always exceeds the materiality threshold", "Errors affect account balances, while fraud only affects disclosures", "Errors are unintentional misstatements, while fraud involves intentional misstatement or omission", "Errors are discovered during fieldwork, while fraud is discovered during planning"]'::jsonb, 2, 'Under AU-C 240.02, the distinguishing factor between fraud and error is intent. An error is an unintentional misstatement in the financial statements, while fraud involves intentional acts by one or more individuals resulting in misstatement. Choice A is incorrect because both errors and fraud can be material or immaterial—the significance depends on the amount and nature of the misstatement, not on whether it was intentional.', 'easy', 1),

-- Q11: medium / L3 — Carry-forward effects of prior-year uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Northgate Retail reported $28,000 in uncorrected misstatements last year that understated cost of goods sold. In the current year, the opening inventory is overstated by the same amount, which offsets through current-year cost of goods sold. The auditor must analyze the effect on the current-year financial statements. Which statement best describes the carry-forward impact?', '["The prior-year misstatement has no effect on current-year statements because it fully reverses through cost of goods sold", "The current-year income statement is correctly stated, but the prior-year comparative income statement remains misstated if presented", "The current-year balance sheet is overstated by $28,000 because the opening inventory error persists", "The auditor should ignore prior-year misstatements when evaluating the current-year financial statements"]'::jsonb, 1, 'Under AU-C 450.A7, when evaluating current-year misstatements, the auditor must consider the effect of prior-year uncorrected misstatements. Although a reversing inventory misstatement corrects the current-year income statement, the comparative prior-year income statement remains misstated because COGS was understated last year. Choice A is incorrect because while the current-year income statement self-corrects, the comparative period presentation still contains the original misstatement that the auditor must evaluate.', 'medium', 3),

-- Q12: easy / L1 — Documentation of accumulated misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the auditor required to document regarding misstatements identified during the audit under AU-C 450?', '["Only misstatements that exceed the materiality threshold", "Only misstatements that management refuses to correct", "Only misstatements resulting from fraud or suspected fraud", "All misstatements accumulated during the audit, including those corrected by management"]'::jsonb, 3, 'Under AU-C 450.05, the auditor must accumulate all misstatements identified during the audit other than those that are clearly trivial. This documentation includes both corrected and uncorrected misstatements, as the complete record informs the auditor''s evaluation of misstatement patterns and overall conclusions. Choice A is incorrect because the accumulation threshold is clearly trivial, which is substantially lower than materiality, and all misstatements above this level must be documented.', 'easy', 1),

-- Q13: medium / L3 — Segregation of duties deficiency severity analysis
(1, 'Misstatements and Control Deficiencies', 'At Cedarbrook Manufacturing, one employee handles all cash receipts, records accounts receivable transactions, and performs the monthly bank reconciliation. The company processes approximately $4.8 million in cash receipts annually, and materiality is set at $200,000. The auditor is analyzing the severity of this control deficiency. What factor most directly supports classifying this as a material weakness?', '["The employee has been in the position for more than five years without a performance review", "The company does not carry fidelity bond insurance for the employee", "The lack of segregation of duties creates a reasonable possibility that a material misstatement could occur and not be prevented or detected on a timely basis", "The annual cash receipts volume exceeds the materiality threshold by more than twenty times"]'::jsonb, 2, 'Under AU-C 265.A12, a material weakness exists when there is a reasonable possibility that a deficiency, individually or combined with others, could result in a material misstatement not being prevented or detected timely. The complete absence of segregation over cash receipts and recording creates this reasonable possibility. Choice D is incorrect because transaction volume alone does not determine severity—the classification depends on whether the deficiency creates a reasonable possibility of an undetected material misstatement.', 'medium', 3),

-- Q14: medium / L2 — Management representation letter for uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'After completing fieldwork for the audit of Pinehurst Consulting Group, the auditor presents a list of $31,000 in uncorrected misstatements to management, who declines to make corrections. Before issuing the report, the auditor requests specific written representations. Under AU-C 580, management should represent that:', '["The effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole", "All misstatements identified were caused by unintentional errors rather than fraud", "The internal control system was effective in preventing all other misstatements during the period", "The misstatements will be corrected in the subsequent reporting period"]'::jsonb, 0, 'Under AU-C 580.A8, the auditor requests that management provide a written representation stating that the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements. A summary of uncorrected items is typically attached to the representation letter. Choice B is incorrect because the management representation focuses on the materiality of uncorrected misstatements, not on whether they resulted from error or fraud.', 'medium', 2),

-- Q15: medium / L3 — Materiality revision effect on previously evaluated misstatements
(1, 'Misstatements and Control Deficiencies', 'Midway through the audit of Thornberry Medical Supplies, the auditor revises materiality downward from $100,000 to $60,000 after discovering that revenue is significantly lower than initially estimated. Previously accumulated uncorrected misstatements total $55,000. The auditor must analyze the impact of this revision. What is the most appropriate response?', '["Maintain the original materiality because it was set using proper benchmarks at planning", "Discard the accumulated misstatements and restart the accumulation process under the new threshold", "Issue a qualified opinion immediately because the uncorrected misstatements now approach revised materiality", "Reevaluate all previously accumulated uncorrected misstatements against the revised materiality level and consider whether additional procedures are necessary"]'::jsonb, 3, 'Under AU-C 320.12, when the auditor becomes aware of information that would have caused a different materiality level, the auditor must revise materiality and evaluate the effect on the audit strategy. Previously accumulated misstatements must be reevaluated against the new threshold. Choice C is incorrect because approaching materiality does not automatically require a qualified opinion—the auditor must first request management to correct the misstatements and evaluate the aggregate effect.', 'medium', 3),

-- Q16: medium / L3 — Recurring control deficiency escalation
(1, 'Misstatements and Control Deficiencies', 'During the current-year audit of Cascade Logistics, the auditor identifies a significant deficiency in the inventory counting process that was also communicated in the prior two years'' audits. Management has not taken corrective action despite repeated communications. The auditor is assessing how this recurring deficiency affects the current audit. What is the most likely impact?', '["The auditor may downgrade the deficiency to a lesser classification because management has been informed", "The auditor should withdraw from the engagement because management is unwilling to remediate", "The recurring nature may indicate a broader weakness in the control environment that elevates the deficiency to a material weakness", "The auditor should reduce testing of inventory because the deficiency has already been documented"]'::jsonb, 2, 'Under AU-C 265.A14, when evaluating control deficiencies, the auditor considers whether management has failed to address previously communicated deficiencies. Repeated failure to remediate a significant deficiency may indicate a broader control environment weakness, potentially elevating the classification to material weakness. Choice A is incorrect because the recurring nature of a deficiency without corrective action worsens rather than mitigates its severity, demonstrating management''s disregard for internal control.', 'medium', 3),

-- Q17: hard / L4 — Evaluate combined known and projected misstatements
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of fieldwork for Westbrook Financial Services, the auditor has accumulated $38,000 in uncorrected misstatements against materiality of $50,000. Sampling results suggest an additional $9,000 in likely undetected misstatements based on projected error. Management argues the $38,000 is below materiality and refuses corrections. The engagement partner must evaluate the overall effect and determine the appropriate response. Which action is most appropriate?', '["Accept the financial statements because the $38,000 in known misstatements is below the $50,000 materiality threshold", "Consider whether the combined effect of known and likely misstatements, totaling $47,000, creates an unacceptable risk that the financial statements are materially misstated", "Require management to correct only the projected $9,000 to bring total known misstatements within an acceptable range", "Issue an unmodified opinion but include an other-matter paragraph disclosing the uncorrected misstatements"]'::jsonb, 1, 'Under AU-C 450.11, when evaluating the aggregate effect of uncorrected misstatements, the auditor considers both identified misstatements and projected misstatements from sampling. The combined $47,000 approaches the $50,000 materiality threshold, creating significant risk. Choice A is incorrect because evaluating only confirmed misstatements ignores the auditor''s obligation under AU-C 450 to consider likely misstatements, which together may indicate the financial statements are materially misstated.', 'hard', 4),

-- Q18: easy / L2 — Identifying misstatement vs control deficiency in a scenario
(1, 'Misstatements and Control Deficiencies', 'Summit Ridge Consulting discovers that its accounts payable clerk consistently miscalculates vendor discount terms, resulting in $6,500 in overpayments during 2025. The clerk''s supervisor reviews and approves all payments. Under auditing standards, the clerk''s calculation errors and the supervisor''s failure to detect them are best classified as:', '["A significant deficiency only, because the errors resulted in financial loss", "A material weakness only, because the supervisor failed to catch the errors", "A control deficiency only, with no resulting misstatement in the financial statements", "Misstatements in the financial statements and a control deficiency in the supervisory review process"]'::jsonb, 3, 'Under AU-C 450 and AU-C 265, the calculation errors resulting in $6,500 in overpayments are misstatements affecting the financial statements, while the supervisor''s failure to detect these errors represents a deficiency in the operation of a control. Both must be evaluated separately. Choice C is incorrect because the $6,500 in overpayments directly affects account balances, constituting misstatements that the auditor must accumulate and evaluate for materiality.', 'easy', 2),

-- Q19: medium / L2 — Communication timing for material weaknesses
(1, 'Misstatements and Control Deficiencies', 'During interim fieldwork in September 2025 for the December 31, 2025 audit of Breckenridge Industries, the auditor identifies a material weakness in the revenue recognition process. The final audit report is not expected until March 2026. Under AU-C 265, the auditor should communicate this material weakness to those charged with governance:', '["Only after the audit is completed and the final report is issued in March 2026", "Within 30 calendar days of completing the entire audit engagement", "Only if the material weakness remains unremediated at year-end", "In writing no later than 60 days after the report release date, though interim communication is encouraged for significant findings"]'::jsonb, 3, 'Under AU-C 265.13, the auditor must communicate significant deficiencies and material weaknesses in writing no later than 60 days after the report release date. However, AU-C 265.A17 encourages timely interim communication, especially for material weaknesses, to give management the opportunity to take corrective action before year-end. Choice A is incorrect because delaying communication of a material weakness until the final report deprives management of the opportunity to address the deficiency before year-end.', 'medium', 2),

-- Q20: medium / L2 — Communication of other (non-significant) deficiencies
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ashford Technologies, the auditor identifies several control deficiencies that do not rise to the level of significant deficiencies or material weaknesses. Under AU-C 265, the auditor''s communication obligation for these lesser deficiencies is:', '["The auditor should communicate these deficiencies to management in writing or orally, and if communicated orally, document the communication", "The auditor has no obligation to communicate deficiencies below the significant deficiency level", "The auditor must communicate all deficiencies directly to the audit committee regardless of severity", "The auditor should include these deficiencies in the same written communication as significant deficiencies and material weaknesses"]'::jsonb, 0, 'Under AU-C 265.12, the auditor should communicate to management control deficiencies that are not significant deficiencies or material weaknesses but are of sufficient importance to merit management''s attention. This communication may be written or oral, and oral communications must be documented. Choice B is incorrect because AU-C 265 does establish a communication obligation for deficiencies below the significant deficiency threshold when they are important enough to warrant management''s attention.', 'medium', 2),

-- Q21: medium / L2 — Applying the clearly trivial threshold with specific amounts
(1, 'Misstatements and Control Deficiencies', 'Cornerstone Retail has overall materiality of $80,000. The auditor establishes a clearly trivial threshold of $2,000. During testing, the auditor discovers three misstatements: $3,100 in understated depreciation, $5,400 in overstated prepaid expenses, and $900 in understated supplies expense. Under AU-C 450, the auditor should accumulate:', '["All three misstatements because they all fall below materiality", "Only the $5,400 misstatement because it is the largest identified amount", "The $3,100 and $5,400 misstatements but not the $900 misstatement", "None of the misstatements because each individually is below the performance materiality threshold"]'::jsonb, 2, 'Under AU-C 450.05, the auditor accumulates all identified misstatements except those that are clearly trivial. With a clearly trivial threshold of $2,000, the $900 misstatement falls below this threshold and need not be accumulated, while the $3,100 and $5,400 misstatements exceed the threshold and must be accumulated. Choice A is incorrect because the clearly trivial threshold, not materiality, determines whether misstatements are accumulated—items below the clearly trivial amount are excluded from the summary of uncorrected misstatements.', 'medium', 2),

-- Q22: easy / L1 — Definition of pervasive effects on financial statements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 705, what does the term ''pervasive'' mean when used to describe the effects of misstatements on financial statements?', '["The effects are not confined to specific elements and represent a substantial proportion of the financial statements", "The effects exceed the overall materiality threshold by more than twice the established amount", "The effects involve fraud rather than unintentional error in the financial statements", "The effects are limited to one financial statement rather than affecting all four statements"]'::jsonb, 0, 'Under AU-C 705.05, pervasive effects are those not confined to specific elements, accounts, or items, that represent a substantial proportion of the financial statements, or that are fundamental to users'' understanding. This concept determines whether a qualified or adverse opinion is appropriate. Choice D is incorrect because pervasive means the effects are widespread throughout the financial statements, the opposite of being limited to a single statement.', 'easy', 1),

-- Q23: medium / L2 — Declining to opine on internal control effectiveness
(1, 'Misstatements and Control Deficiencies', 'After identifying a material weakness in Riverview Construction''s payroll processing, the auditor drafts a written communication for those charged with governance. The audit committee chair requests that the auditor also provide an overall opinion on the effectiveness of internal control. Under AU-C 265, the auditor should:', '["Provide the requested opinion because the auditor has sufficient knowledge of the internal control system", "Decline to provide an overall opinion on internal control effectiveness, as AU-C 265 communications are not designed for that purpose", "Provide the opinion only if the engagement letter includes internal control reporting as a service", "Provide a limited opinion covering only the areas tested during the financial statement audit"]'::jsonb, 1, 'Under AU-C 265.A1, the auditor''s communication of control deficiencies identified during a financial statement audit is not a substitute for an engagement to report on internal control. The auditor should not express an overall opinion on internal control effectiveness based solely on deficiencies identified in a financial statement audit. Choice A is incorrect because a financial statement audit does not encompass sufficient testing of all controls to support an opinion on the overall effectiveness of internal control.', 'medium', 2),

-- Q24: medium / L2 — Group audit aggregation of component misstatements
(1, 'Misstatements and Control Deficiencies', 'Greenfield Consolidated has three subsidiaries audited by component auditors. The group engagement partner receives summaries of uncorrected misstatements from each component: Subsidiary A reports $18,000, Subsidiary B reports $12,000, and Subsidiary C reports $8,000. Group materiality is $50,000 and component materiality is $25,000 each. Under AU-C 600, the group engagement partner should:', '["Evaluate each subsidiary''s misstatements only against the $25,000 component materiality", "Accept the misstatements because no single subsidiary exceeds either materiality level", "Request that each component auditor correct all misstatements before consolidation", "Aggregate all component misstatements and evaluate them against group materiality along with any group-level misstatements"]'::jsonb, 3, 'Under AU-C 600.A62, the group engagement partner must evaluate the aggregate effect of uncorrected misstatements from all components, plus any group-level misstatements, against group materiality. The combined $38,000 from three subsidiaries must be evaluated at the group level. Choice B is incorrect because misstatements that are individually immaterial at the component level may be material in the aggregate when combined across all components and evaluated against group materiality.', 'medium', 2),

-- Q25: hard / L4 — Evaluating competing classifications for journal entry review deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Aspen Valley Health System, the auditor discovers that the CFO personally approves all journal entries without independent review, including month-end closing entries and non-routine adjustments. No misstatements were found in the current year. The CFO has 20 years of experience and an excellent track record. The audit committee argues the deficiency is a significant deficiency, not a material weakness, citing clean testing results and the CFO''s competence. Which assessment is most appropriate?', '["Classify as a significant deficiency because no actual misstatements were identified in the current year", "Classify as a significant deficiency because the CFO''s experience serves as a compensating factor", "Classify as a material weakness because the absence of independent review over journal entries creates a reasonable possibility of undetected material misstatement regardless of the CFO''s competence", "Defer to the audit committee''s classification because they have the most complete understanding of the control environment"]'::jsonb, 2, 'Under AU-C 265.A13, the severity of a control deficiency depends on the potential for misstatement, not on whether a misstatement actually occurred. The absence of independent review over journal entries represents a material weakness because it creates a reasonable possibility that a material misstatement could occur and not be detected, regardless of the preparer''s competence. Choice A is incorrect because AU-C 265 requires the auditor to evaluate the potential magnitude of misstatement, not limit the assessment to actual results from current-year testing.', 'hard', 4),

-- Q26: easy / L1 — Modified opinion types for misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 705, which types of modified opinions may an auditor issue when material misstatements exist in the financial statements?', '["Disclaimer of opinion and adverse opinion", "Qualified opinion and adverse opinion", "Unmodified opinion with emphasis-of-matter paragraph and qualified opinion", "Adverse opinion and going-concern opinion"]'::jsonb, 1, 'Under AU-C 705.07–08, when material misstatements exist, the auditor expresses either a qualified opinion (material but not pervasive) or an adverse opinion (material and pervasive). A disclaimer of opinion relates to scope limitations, not misstatements. Choice A is incorrect because a disclaimer of opinion is issued when the auditor cannot obtain sufficient appropriate audit evidence, which is a scope limitation scenario, not a misstatement scenario.', 'easy', 1),

-- Q27: easy / L1 — Fraud indicator in identified misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 240, which characteristic of an identified misstatement most strongly suggests it may be the result of fraud rather than error?', '["The misstatement involves intentional manipulation of journal entries to achieve a desired financial result", "The misstatement resulted from an incorrect application of an accounting standard", "The misstatement was discovered during substantive testing of account balances", "The misstatement exceeds the performance materiality threshold established during planning"]'::jsonb, 0, 'Under AU-C 240.A1, fraud involves intentional acts such as deliberate manipulation of journal entries, falsification of documents, or intentional omissions. The presence of intentional manipulation distinguishes fraud from error. Choice B is incorrect because misapplication of accounting standards typically represents an unintentional error, and neither the method of discovery nor the size of the misstatement alone determines whether it constitutes fraud.', 'easy', 1),

-- Q28: easy / L1 — COSO component most associated with control deficiency root cause
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 315, which COSO framework component is most directly associated with evaluating whether identified control deficiencies indicate a broader organizational problem?', '["Risk assessment", "Control environment", "Information and communication", "Monitoring activities"]'::jsonb, 1, 'Under AU-C 315.14, the control environment sets the tone of the organization and includes governance structure, management philosophy, and commitment to competence. Pervasive control deficiencies often trace back to weaknesses in the control environment because it establishes management''s attitude toward internal control. Choice D is incorrect because while monitoring activities detect control deficiencies, the control environment determines the broader organizational context in which those deficiencies arise and whether they reflect systemic governance issues.', 'easy', 1),

-- Q29: hard / L3 — Analyze impact of prior-period misstatements on comparative statements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Brookfield Enterprises for the year ended December 31, 2025, the auditor identifies $75,000 in uncorrected misstatements overstating 2025 revenue. Materiality is $60,000. The 2024 comparative financial statements were audited by a predecessor auditor who issued an unmodified opinion. The current auditor also discovers that $45,000 of the 2025 misstatements originated from errors in the 2024 period that were not detected by the predecessor. What is the most appropriate response regarding the comparative financial statements?', '["Consider whether the 2024 comparative statements require restatement and, if not restated, evaluate the effect on the current-year auditor''s report", "Reissue the predecessor auditor''s report with a modification because the 2024 statements contain misstatements", "Issue an unmodified opinion on both years because the 2024 misstatements were below the predecessor''s materiality", "Exclude the 2024 comparative statements from the current-year financial statement presentation"]'::jsonb, 0, 'Under AU-C 710.12, when the current auditor becomes aware of misstatements affecting comparative financial statements, the auditor should request management to correct the prior-period statements. If management does not restate, the auditor must evaluate whether the misstatements are material to the prior period and modify the opinion accordingly. Choice C is incorrect because the current auditor cannot assume the predecessor''s materiality level was appropriate and must independently evaluate the materiality of discovered misstatements as they affect the 2024 comparative statements.', 'hard', 3),

-- Q30: medium / L3 — Subsequent event effect on uncorrected misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'After the year-end date but before issuing the audit report for Harborview Marine Services, the auditor learns that a customer with a $95,000 accounts receivable balance filed for bankruptcy in January 2026. This receivable was included in the $30,000 of uncorrected misstatements related to the allowance for doubtful accounts. Materiality is $80,000. How does this subsequent event affect the evaluation of uncorrected misstatements?', '["The subsequent event has no effect on uncorrected misstatements because it occurred after the balance sheet date", "The subsequent event provides additional evidence that the receivable balance may have been impaired at year-end, requiring the auditor to reassess whether the uncorrected misstatements are now material", "The auditor should add the full $95,000 to the uncorrected misstatements summary, automatically bringing the total above materiality", "The auditor should remove the $30,000 from uncorrected misstatements and reclassify it as a subsequent event disclosure"]'::jsonb, 1, 'Under AU-C 560.12, subsequent events provide evidence of conditions that existed at the balance sheet date. A customer bankruptcy shortly after year-end suggests the receivable may have been impaired as of December 31, potentially increasing the misstatement related to accounts receivable and requiring reassessment of the aggregate uncorrected misstatements. Choice A is incorrect because AU-C 560 specifically requires the auditor to consider subsequent events as evidence about conditions existing at the balance sheet date, which directly affects the evaluation of year-end account balances.', 'medium', 3)
;

COMMIT;
